const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args && typeof source.args === 'object' ? source.args : {};
const tool = String(source.tool || args.tool || '').trim();
const text = String(args.instruction || args.text || args.prompt || source.text || source.rawText || '').trim();
function clean(value) {
  return String(value || '').trim();
}

function extractFirstUrl(value) {
  const match = String(value || '').match(/https?:\/\/[^\s<>\]\)"']+/i);
  return match ? match[0].replace(/[),.;!?]+$/, '') : '';
}

function parseRepoContext() {
  const repoInput = clean(args.repo || source.repo || '');
  const ownerInput = clean(args.owner || source.owner || '');
  const repoNameInput = clean(args.repoName || args.repo_name || source.repoName || source.repo_name || '');
  const repoUrlInput = clean(args.repoUrl || args.repo_url || source.repoUrl || source.repo_url || '');
  const pathInput = clean(args.path || args.filePath || args.file_path || source.path || source.filePath || source.file_path || '');
  const refInput = clean(args.ref || source.ref || '');

  const rawSource = [repoUrlInput, repoInput, ownerInput, repoNameInput, text].filter(Boolean).join(' ');
  const urlMatch = rawSource.match(/https?:\/\/github\.com\/([^/\s]+)\/([^/\s]+)(?:\/(?:tree|blob)\/([^/\s]+)(?:\/([^\s?#]+))?)?/i);
  if (urlMatch) {
    const owner = clean(urlMatch[1]);
    const repoName = clean(urlMatch[2]);
    const ref = clean(urlMatch[3] || refInput);
    const path = clean(urlMatch[4] || pathInput);
    return {
      repo: `${owner}/${repoName}`,
      owner,
      repoName,
      repoUrl: `https://github.com/${owner}/${repoName}`,
      path,
      ref,
    };
  }

  let owner = ownerInput;
  let repoName = repoNameInput;
  if (!owner && !repoName && repoInput.includes('/')) {
    const [ownerPart, repoPart] = repoInput.split('/', 2);
    owner = clean(ownerPart);
    repoName = clean(repoPart);
  } else if (owner && !repoName) {
    repoName = clean(repoInput);
  } else if (!owner && repoName && repoInput) {
    owner = clean(repoInput);
  }

  const repo = owner && repoName ? `${owner}/${repoName}` : clean(repoInput);
  const repoUrl = repo && repo.includes('/') ? `https://github.com/${repo}` : repoUrlInput;
  return {
    repo,
    owner,
    repoName,
    repoUrl,
    path: pathInput,
    ref: refInput,
  };
}

const repoContext = parseRepoContext();
const queryInput = clean(args.query || source.query || '');
const topicInput = clean(args.topic || source.topic || '');
const languageInput = clean(args.language || source.language || '');
const sortByInput = clean(args.sortBy || args.sort_by || source.sortBy || source.sort_by || '');
const usernameInput = clean(args.username || source.username || '');
const visibilityInput = clean(args.visibility || source.visibility || '');
const pageInput = Number(args.page || source.page || 1) || 1;
const limitInput = Number(args.limit || source.limit || 0) || 0;
const maxCharsInput = Number(args.maxChars || args.max_chars || source.maxChars || source.max_chars || 0) || 0;
const baseInput = clean(args.base || source.base || '');
const headInput = clean(args.head || source.head || '');
const refInput = clean(args.ref || source.ref || repoContext.ref || '');
const pathInput = clean(args.path || args.filePath || args.file_path || repoContext.path || '');
let useAuth = ['github.search_code', 'github.search_repos', 'github.list_user_repos', 'github.get_repo_tree'].includes(tool);


function encodeRepoPath(path) {
  return String(path || '')
    .split('/')
    .filter(Boolean)
    .map((segment) => encodeURIComponent(segment))
    .join('/');
}

function buildQueryString(params) {
  return Object.entries(params)
    .filter(([, value]) => value !== undefined && value !== null && String(value).trim() !== '')
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
    .join('&');
}

const repo = repoContext.repo;
const owner = repoContext.owner;
const repoName = repoContext.repoName;
const repoUrl = repoContext.repoUrl;
const authHeader = '';
const apiBase = 'https://api.github.com';
let method = 'GET';
let endpointPath = '';
let requestUrl = '';
let summaryLabel = '';
let query = queryInput;
let topic = topicInput;
let language = languageInput;
let sortBy = sortByInput;
let username = usernameInput;
let visibility = visibilityInput;
let page = pageInput > 0 ? pageInput : 1;
let limit = limitInput > 0 ? limitInput : 20;
let maxChars = maxCharsInput > 0 ? maxCharsInput : 4000;
let base = baseInput;
let head = headInput;
let ref = refInput;
let path = pathInput.replace(/^\/+/, '');
let releaseTag = clean(args.tag || source.tag || '');
let releaseId = clean(args.releaseId || args.release_id || source.releaseId || source.release_id || '');
let itemNumber = clean(args.number || source.number || '');
let itemState = clean(args.state || source.state || '');
let itemLabels = clean(args.labels || source.labels || '');

switch (tool) {
  case 'github.get_repo':
  case 'github_get_repo':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}`;
    summaryLabel = 'repo';
    break;
  case 'github.list_branches':
  case 'github_list_branches':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}/branches?per_page=${Math.max(1, Math.min(limit, 100))}`;
    summaryLabel = 'branches';
    break;
  case 'github.list_commits':
  case 'github_list_commits':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}/commits?per_page=${Math.max(1, Math.min(limit, 100))}`;
    if (ref) {
      endpointPath += `&sha=${encodeURIComponent(ref)}`;
    }
    summaryLabel = 'commits';
    break;
  case 'github.get_commit':
  case 'github_get_commit':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    if (!ref) {
      return [{ json: { ok: false, error: 'Missing commit SHA or ref.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}/commits/${encodeURIComponent(ref)}`;
    summaryLabel = 'commit';
    break;
  case 'github.list_releases':
  case 'github_list_releases':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}/releases?per_page=${Math.max(1, Math.min(limit, 100))}&page=${Math.max(1, page)}`;
    summaryLabel = 'releases';
    break;
  case 'github.get_release':
  case 'github_get_release':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    if (releaseTag) {
      endpointPath = `/repos/${repo}/releases/tags/${encodeURIComponent(releaseTag)}`;
    } else if (releaseId && releaseId !== 'latest') {
      endpointPath = `/repos/${repo}/releases/${encodeURIComponent(releaseId)}`;
    } else {
      endpointPath = `/repos/${repo}/releases/latest`;
    }
    summaryLabel = 'release';
    break;
  case 'github.list_pull_requests':
  case 'github_list_pull_requests':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}/pulls?${buildQueryString({ state: itemState || 'open', per_page: Math.max(1, Math.min(limit, 100)), page: Math.max(1, page) })}`;
    summaryLabel = 'pull_requests';
    break;
  case 'github.get_pull_request':
  case 'github_get_pull_request':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    if (!itemNumber) {
      return [{ json: { ok: false, error: 'Missing pull request number.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}/pulls/${encodeURIComponent(itemNumber)}`;
    summaryLabel = 'pull_request';
    break;
  case 'github.list_issues':
  case 'github_list_issues':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}/issues?${buildQueryString({ state: itemState || 'open', labels: itemLabels, per_page: Math.max(1, Math.min(limit, 100)), page: Math.max(1, page) })}`;
    summaryLabel = 'issues';
    break;
  case 'github.get_issue':
  case 'github_get_issue':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    if (!itemNumber) {
      return [{ json: { ok: false, error: 'Missing issue number.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}/issues/${encodeURIComponent(itemNumber)}`;
    summaryLabel = 'issue';
    break;
  case 'github.get_file':
  case 'github.get_file':
  case 'github_get_file':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    if (!path) {
      return [{ json: { ok: false, error: 'Missing file path.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}/contents/${encodeRepoPath(path)}`;
    if (ref) {
      endpointPath += `?ref=${encodeURIComponent(ref)}`;
    }
    summaryLabel = 'file';
    break;
  case 'github.get_repo_tree':
  case 'github_get_repo_tree':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}/contents${path ? `/${encodeRepoPath(path)}` : ''}`;
    if (ref) {
      endpointPath += `${endpointPath.includes('?') ? '&' : '?'}ref=${encodeURIComponent(ref)}`;
    }
    summaryLabel = 'tree';
    useAuth = true;
    break;
  case 'github.list_user_repos':
  case 'github_list_user_repos':
    if (!username) {
      endpointPath = `/user/repos?per_page=${Math.max(1, Math.min(limit, 100))}&page=${Math.max(1, page)}`;
    } else {
      endpointPath = `/users/${encodeURIComponent(username)}/repos?per_page=${Math.max(1, Math.min(limit, 100))}&page=${Math.max(1, page)}`;
    }
    if (visibility) {
      endpointPath += `${endpointPath.includes('?') ? '&' : '?'}visibility=${encodeURIComponent(visibility)}`;
    }
    summaryLabel = 'user_repos';
    useAuth = true;
    break;
  case 'github.search_repos':
  case 'github_search_repos':
    if (!query && !topic) {
      return [{ json: { ok: false, error: 'Missing search query.', tool, requestId: clean(source.requestId || '') } }];
    }
    if (!query) {
      query = topic;
    }
    const qParts = [query].filter(Boolean);
    if (topic && !qParts.join(' ').includes(`topic:${topic}`)) {
      qParts.push(`topic:${topic}`);
    }
    if (language) {
      qParts.push(`language:${language}`);
    }
    const sortMap = {
      best_match: '',
      most_stars: 'stars',
      fewest_stars: 'stars',
      most_forks: 'forks',
      fewest_forks: 'forks',
      recently_updated: 'updated',
      least_recently_updated: 'updated',
    };
    const orderMap = {
      best_match: 'desc',
      most_stars: 'desc',
      fewest_stars: 'asc',
      most_forks: 'desc',
      fewest_forks: 'asc',
      recently_updated: 'desc',
      least_recently_updated: 'asc',
    };
    const sortField = sortMap[sortBy] || '';
    const orderField = orderMap[sortBy] || 'desc';
    endpointPath = `/search/repositories?${buildQueryString({
      q: qParts.join(' ').trim(),
      sort: sortField,
      order: sortField ? orderField : '',
      per_page: Math.max(1, Math.min(limit, 100)),
      page: Math.max(1, page),
    })}`;
    summaryLabel = 'search_repos';
    useAuth = true;
    break;
  case 'github.search_code':
  case 'github_search_code':
    if (!query) {
      return [{ json: { ok: false, error: 'Missing search query.', tool, requestId: clean(source.requestId || '') } }];
    }
    if (repo && !/\brepo:/.test(query)) {
      query = `${query} repo:${repo}`.trim();
    }
    endpointPath = `/search/code?${buildQueryString({ q: query })}`;
    summaryLabel = 'search';
    break;
  case 'github.get_diff':
  case 'github_get_diff':
    if (!repo) {
      return [{ json: { ok: false, error: 'Missing GitHub repository.', tool, requestId: clean(source.requestId || '') } }];
    }
    if (!base || !head) {
      const compareMatch = text.match(/\b([A-Za-z0-9_.:/-]+)\.\.\.([A-Za-z0-9_.:/-]+)\b/);
      if (compareMatch) {
        base = base || clean(compareMatch[1]);
        head = head || clean(compareMatch[2]);
      }
    }
    if (!base || !head) {
      return [{ json: { ok: false, error: 'Missing base/head refs for diff.', tool, requestId: clean(source.requestId || '') } }];
    }
    endpointPath = `/repos/${repo}/compare/${encodeURIComponent(base)}...${encodeURIComponent(head)}`;
    summaryLabel = 'diff';
    break;
  default:
    return [{ json: { ok: false, error: `Unsupported GitHub tool: ${tool}`, tool, requestId: clean(source.requestId || '') } }];
}

requestUrl = `${apiBase}${endpointPath}`;

return [{
  json: {
    ok: true,
    tool,
    summaryLabel,
    apiBase,
    requestUrl,
    method,
    endpointPath,
    authHeader,
    repo,
    owner,
    repoName,
    repoUrl,
    path,
    ref,
    base,
    head,
    query,
    limit,
    maxChars,
    requestId: clean(source.requestId || ''),
    originChatId: clean(source.originChatId || source.chatId || ''),
    deliveryMode: clean(source.deliveryMode || 'return') || 'return',
    useAuth,
  }
}];

const source = $('Normalize GitHub Input').item.json || {};
const items = $input.all().map((item) => item.json || {});
const first = items[0] || {};
const output = items.length > 1 ? items : first;

function clean(value) {
  return String(value || '').trim();
}

function normalizeArrayRows(rows, formatter) {
  if (!Array.isArray(rows) || !rows.length) return '';
  return rows.slice(0, 10).map(formatter).filter(Boolean).join('\n');
}

function formatLabelNames(labels) {
  if (!Array.isArray(labels) || !labels.length) return '';
  return labels
    .map((label) => clean(label.name || label.title || label))
    .filter(Boolean)
    .slice(0, 5)
    .join(', ');
}

function formatReleaseRow(release, index) {
  const tag = clean(release.tag_name || release.name || `release-${index + 1}`);
  const title = clean(release.name || '');
  const publishedAt = clean(release.published_at || release.created_at || '');
  const url = clean(release.html_url || '');
  const markers = [release.draft ? 'draft' : '', release.prerelease ? 'prerelease' : '', publishedAt ? `published ${publishedAt.slice(0, 10)}` : ''].filter(Boolean).join(' | ');
  return `${index + 1}. ${tag}${title && title !== tag ? ` | ${title}` : ''}${markers ? ` | ${markers}` : ''}${url ? ` | ${url}` : ''}`.trim();
}

function formatPullRequestRow(pr, index) {
  const number = Number(pr.number || index + 1);
  const title = clean(pr.title || pr.name || '');
  const state = clean(pr.state || '');
  const url = clean(pr.html_url || '');
  const markers = [pr.draft ? 'draft' : '', clean(pr.user?.login || ''), pr.merged_at ? 'merged' : ''].filter(Boolean).join(' | ');
  return `${index + 1}. #${number}${title ? ` ${title}` : ''}${state ? ` | ${state}` : ''}${markers ? ` | ${markers}` : ''}${url ? ` | ${url}` : ''}`.trim();
}

function formatIssueRow(issue, index) {
  const number = Number(issue.number || index + 1);
  const title = clean(issue.title || issue.name || '');
  const state = clean(issue.state || '');
  const url = clean(issue.html_url || '');
  const labels = formatLabelNames(issue.labels || []);
  const author = clean(issue.user?.login || '');
  const markers = [author, labels].filter(Boolean).join(' | ');
  return `${index + 1}. #${number}${title ? ` ${title}` : ''}${state ? ` | ${state}` : ''}${markers ? ` | ${markers}` : ''}${url ? ` | ${url}` : ''}`.trim();
}

const statusCode = Number(first.statusCode || first.status || 0) || 0;
const ok = first.ok !== false && !first.message && !first.errors && (!statusCode || (statusCode >= 200 && statusCode < 300));
const data = first.body ?? first.data ?? (items.length > 1 ? items : first);

let text = '';
let links = [];
let result = data;

if (!ok) {
  const rawMessage = clean(first.message || first.error || (data && data.message) || `GitHub API error ${statusCode}`);
  const isSearchAuthError = source.summaryLabel === 'search' && (statusCode === 401 || statusCode === 403 || /auth|credential|token/i.test(rawMessage));
  text = isSearchAuthError ? 'GITHUB_TOKEN is required for GitHub code search.' : rawMessage;
  result = data;
} else if (source.summaryLabel === 'repo') {
  const repoData = Array.isArray(data) ? data[0] || {} : data;
  text = [
    clean(repoData.full_name || repoData.name),
    clean(repoData.description),
    clean(repoData.default_branch ? `Default branch: ${repoData.default_branch}` : ''),
    clean(repoData.html_url ? `URL: ${repoData.html_url}` : ''),
  ].filter(Boolean).join('\n');
  links = repoData.html_url ? [repoData.html_url] : [];
  result = repoData;
} else if (source.summaryLabel === 'branches') {
  const rows = Array.isArray(data) ? data : items;
  text = normalizeArrayRows(rows, (branch, index) => {
    const name = clean(branch.name || `branch-${index + 1}`);
    const sha = clean(branch.commit?.sha || '');
    return sha ? `${index + 1}. ${name} (${sha})` : `${index + 1}. ${name}`;
  });
  result = rows;
} else if (source.summaryLabel === 'commits') {
  const rows = Array.isArray(data) ? data : items;
  text = normalizeArrayRows(rows, (commit, index) => {
    const sha = clean(commit.sha || '');
    const message = clean(commit.commit?.message || '').split('\n')[0];
    const author = clean(commit.commit?.author?.name || commit.commit?.committer?.name || '');
    const date = clean(commit.commit?.author?.date || commit.commit?.committer?.date || '');
    return `${index + 1}. ${sha.slice(0, 8)} ${message}${author ? ` | ${author}` : ''}${date ? ` | ${date}` : ''}`.trim();
  });
  result = rows;
} else if (source.summaryLabel === 'commit') {
  const commitData = Array.isArray(data) ? data[0] || {} : data;
  const sha = clean(commitData.sha || '');
  const message = clean(commitData.commit?.message || '').split('\n')[0];
  const author = clean(commitData.commit?.author?.name || commitData.commit?.committer?.name || '');
  const date = clean(commitData.commit?.author?.date || commitData.commit?.committer?.date || '');
  const files = Array.isArray(commitData.files) ? commitData.files : [];
  text = [
    sha ? `SHA: ${sha}` : '',
    message ? `Message: ${message}` : '',
    author ? `Author: ${author}` : '',
    date ? `Date: ${date}` : '',
    files.length ? `Files changed: ${files.length}` : '',
    files.length ? `Files: ${files.slice(0, 10).map((file) => clean(file.filename)).filter(Boolean).join(', ')}` : '',
  ].filter(Boolean).join('\n');
  result = commitData;
} else if (source.summaryLabel === 'file') {
  if (Array.isArray(data)) {
    text = data.slice(0, 10).map((entry, index) => `${index + 1}. ${clean(entry.path || entry.name || '')}`).filter(Boolean).join('\n');
    result = data;
  } else {
    const fileName = clean(data.name || data.path || source.path || '');
    const encoding = clean(data.encoding || '');
    let content = clean(data.content || '');
    if (encoding === 'base64' && content) {
      try {
        content = Buffer.from(content.replace(/\n/g, ''), 'base64').toString('utf8');
      } catch (error) {
        content = clean(data.content || '');
      }
    }
    const trimmed = content.slice(0, Math.max(0, source.maxChars || 4000));
    text = [
      fileName ? `File: ${fileName}` : '',
      data.html_url ? `URL: ${data.html_url}` : '',
      trimmed ? `Content:\n${trimmed}` : '',
    ].filter(Boolean).join('\n');
    links = data.html_url ? [data.html_url] : [];
    result = data;
  }
} else if (source.summaryLabel === 'user_repos') {
  const rows = Array.isArray(data) ? data : items;
  text = normalizeArrayRows(rows, (repoItem, index) => {
    const name = clean(repoItem.full_name || repoItem.name || `repo-${index + 1}`);
    const description = clean(repoItem.description || '');
    const stars = Number(repoItem.stargazers_count || 0);
    const language = clean(repoItem.language || '');
    const htmlUrl = clean(repoItem.html_url || '');
    const extra = [
      stars ? `${stars}★` : '',
      language,
    ].filter(Boolean).join(' | ');
    return `${index + 1}. ${name}${extra ? ` | ${extra}` : ''}${description ? ` | ${description}` : ''}${htmlUrl ? ` | ${htmlUrl}` : ''}`.trim();
  });
  links = rows.map((item) => clean(item.html_url || '')).filter(Boolean).slice(0, 10);
  result = rows;
} else if (source.summaryLabel === 'releases') {
  const rows = Array.isArray(data) ? data : items;
  text = normalizeArrayRows(rows, formatReleaseRow);
  links = rows.map((item) => clean(item.html_url || '')).filter(Boolean).slice(0, 10);
  result = rows;
} else if (source.summaryLabel === 'release') {
  const release = Array.isArray(data) ? data[0] || {} : data;
  text = [
    clean(release.tag_name || release.name || ''),
    clean(release.name && release.name !== release.tag_name ? `Title: ${release.name}` : ''),
    clean(release.draft ? 'Draft: yes' : ''),
    clean(release.prerelease ? 'Pre-release: yes' : ''),
    clean(release.published_at ? `Published: ${release.published_at}` : ''),
    clean(release.body ? `Notes: ${String(release.body).split('\n').slice(0, 4).join(' ')}` : ''),
    clean(release.html_url ? `URL: ${release.html_url}` : ''),
  ].filter(Boolean).join('\n');
  links = release.html_url ? [release.html_url] : [];
  result = release;
} else if (source.summaryLabel === 'pull_requests') {
  const rows = Array.isArray(data) ? data : items;
  text = normalizeArrayRows(rows, formatPullRequestRow);
  links = rows.map((item) => clean(item.html_url || '')).filter(Boolean).slice(0, 10);
  result = rows;
} else if (source.summaryLabel === 'pull_request') {
  const pullRequest = Array.isArray(data) ? data[0] || {} : data;
  text = [
    clean(pullRequest.number ? `#${pullRequest.number}` : ''),
    clean(pullRequest.title || ''),
    clean(pullRequest.state ? `State: ${pullRequest.state}` : ''),
    clean(pullRequest.draft ? 'Draft: yes' : ''),
    clean(pullRequest.user?.login ? `Author: ${pullRequest.user.login}` : ''),
    clean(pullRequest.body ? `Summary: ${String(pullRequest.body).split('\n').slice(0, 4).join(' ')}` : ''),
    clean(pullRequest.html_url ? `URL: ${pullRequest.html_url}` : ''),
  ].filter(Boolean).join('\n');
  links = pullRequest.html_url ? [pullRequest.html_url] : [];
  result = pullRequest;
} else if (source.summaryLabel === 'issues') {
  const rows = (Array.isArray(data) ? data : items).filter((item) => !item.pull_request);
  text = normalizeArrayRows(rows, formatIssueRow);
  links = rows.map((item) => clean(item.html_url || '')).filter(Boolean).slice(0, 10);
  result = rows;
} else if (source.summaryLabel === 'issue') {
  const issue = Array.isArray(data) ? data[0] || {} : data;
  text = [
    clean(issue.number ? `#${issue.number}` : ''),
    clean(issue.title || ''),
    clean(issue.state ? `State: ${issue.state}` : ''),
    clean(issue.user?.login ? `Author: ${issue.user.login}` : ''),
    clean(formatLabelNames(issue.labels || []) ? `Labels: ${formatLabelNames(issue.labels || [])}` : ''),
    clean(issue.body ? `Summary: ${String(issue.body).split('\n').slice(0, 4).join(' ')}` : ''),
    clean(issue.html_url ? `URL: ${issue.html_url}` : ''),
  ].filter(Boolean).join('\n');
  links = issue.html_url ? [issue.html_url] : [];
  result = issue;
} else if (source.summaryLabel === 'search_repos') {
  const rows = Array.isArray(data.items) ? data.items : [];
  text = [
    data.total_count ? `Total matched: ${data.total_count}` : '',
    normalizeArrayRows(rows, (repoItem, index) => {
      const name = clean(repoItem.full_name || repoItem.name || `repo-${index + 1}`);
      const description = clean(repoItem.description || '');
      const stars = Number(repoItem.stargazers_count || 0);
      const forks = Number(repoItem.forks_count || 0);
      const language = clean(repoItem.language || '');
      const htmlUrl = clean(repoItem.html_url || '');
      const metrics = [
        stars ? `${stars}★` : '',
        forks ? `${forks}⑂` : '',
        language,
      ].filter(Boolean).join(' | ');
      return `${index + 1}. ${name}${metrics ? ` | ${metrics}` : ''}${description ? ` | ${description}` : ''}${htmlUrl ? ` | ${htmlUrl}` : ''}`.trim();
    }),
  ].filter(Boolean).join('\n');
  links = rows.map((item) => clean(item.html_url || '')).filter(Boolean).slice(0, 10);
  result = rows;
} else if (source.summaryLabel === 'tree') {
  const rows = Array.isArray(data) ? data : items;
  const visibleRows = rows.slice(0, 20);
  text = [
    source.path ? `Path: ${source.path}` : 'Path: /',
    rows.length ? `Items: ${rows.length}` : '',
    normalizeArrayRows(visibleRows, (entry, index) => {
      const name = clean(entry.name || entry.path || `item-${index + 1}`);
      const type = clean(entry.type || '');
      const pathName = clean(entry.path || '');
      const suffix = type ? ` [${type}]` : '';
      return `${index + 1}. ${name}${suffix}${pathName && pathName !== name ? ` :: ${pathName}` : ''}`.trim();
    }),
  ].filter(Boolean).join('\n');
  links = rows.map((item) => clean(item.html_url || '')).filter(Boolean).slice(0, 10);
  result = rows;
} else if (source.summaryLabel === 'search') {

  const itemsList = Array.isArray(data.items) ? data.items : [];
  text = normalizeArrayRows(itemsList, (item, index) => {
    const path = clean(item.path || '');
    const repo = clean(item.repository?.full_name || item.repository?.name || '');
    const htmlUrl = clean(item.html_url || '');
    return `${index + 1}. ${repo}${path ? ` :: ${path}` : ''}${htmlUrl ? ` :: ${htmlUrl}` : ''}`.trim();
  });
  links = itemsList.map((item) => clean(item.html_url || '')).filter(Boolean).slice(0, 10);
  result = itemsList;
} else if (source.summaryLabel === 'diff') {
  const diffData = Array.isArray(data) ? data[0] || {} : data;
  const files = Array.isArray(diffData.files) ? diffData.files : [];
  const commits = Array.isArray(diffData.commits) ? diffData.commits : [];
  text = [
    clean(diffData.html_url ? `URL: ${diffData.html_url}` : ''),
    commits.length ? `Commits: ${commits.length}` : '',
    files.length ? `Files changed: ${files.length}` : '',
    files.length ? `Files: ${files.slice(0, 10).map((file) => {
      const name = clean(file.filename || '');
      const changes = [file.additions, file.deletions, file.changes].map((n) => Number(n || 0));
      return `${name}${changes[2] ? ` (+${changes[0]}/-${changes[1]})` : ''}`.trim();
    }).filter(Boolean).join(', ')}` : '',
  ].filter(Boolean).join('\n');
  links = diffData.html_url ? [diffData.html_url] : [];
  result = diffData;
} else {
  text = clean(first.message || first.error || JSON.stringify(data));
}

if (!text) {
  text = ok ? 'GitHub request completed.' : 'GitHub request failed.';
}

return [{
  json: {
    ok,
    statusCode,
    tool: source.tool || '',
    summaryLabel: source.summaryLabel || '',
    repo: source.repo || '',
    owner: source.owner || '',
    repoName: source.repoName || '',
    repoUrl: source.repoUrl || '',
    path: source.path || '',
    ref: source.ref || '',
    base: source.base || '',
    head: source.head || '',
    query: source.query || '',
    limit: source.limit || 0,
    maxChars: source.maxChars || 0,
    requestId: source.requestId || '',
    originChatId: source.originChatId || '',
    deliveryMode: source.deliveryMode || 'return',
    text,
    result,
    links: links.slice(0, 10),
    data: output,
    followupPrompt: ['search_repos', 'user_repos', 'releases', 'pull_requests', 'issues'].includes(source.summaryLabel) ? 'Anh muốn mình đi sâu mục nào? Trả số thứ tự, tag, number hoặc tên mục.' : ['tree', 'release', 'pull_request', 'issue'].includes(source.summaryLabel) ? 'Anh muốn mình đi sâu mục nào tiếp theo?' : '',
    meta: {
      deliveryMode: source.deliveryMode || 'return',
      originChatId: source.originChatId || '',
    },
  }
}];

const source = $('Normalize GitHub Input').item.json || {};
return [{
  json: {
    ok: false,
    error: source.ok === false ? source.error : 'GitHub request failed.',
    tool: source.tool || '',
    summaryLabel: source.summaryLabel || '',
    requestId: source.requestId || '',
    originChatId: source.originChatId || '',
    deliveryMode: source.deliveryMode || 'return'
  }
}];
